powerpagecomponent.content:
{
  "source": "{% comment %}
sections--acceptance-router (DEBUG HARDENED)

✅ Owns full application layout
✅ Loads acceptance + determines lifecycle state
✅ Routes to correct UI component
✅ Provides granular debug checkpoints
✅ Safer field access to reduce runtime invocation errors
{% endcomment %}

{% assign DEBUG = request.params.debug == '1' %}
{% assign acceptanceId = request.params.acceptanceid | default: '' | strip %}
{% assign waitingForStatus = request.params.waitforpayment == '1' %}
{% assign flowStatusHint = request.params.flowstatus | default: '' | downcase | strip %}
{% assign forceCompletedFromFlow = false %}
{% if flowStatusHint == 'completed' %}
  {% assign forceCompletedFromFlow = true %}
{% endif %}

{% assign STATUS_DRAFT = 0 %}
{% assign STATUS_PENDING_INFORMATION = 815390000 %}
{% assign STATUS_PENDING_PAYMENT = 815390001 %}
{% assign STATUS_PENDING_APPROVAL = 815390002 %}
{% assign STATUS_COMPLETED = 815390003 %}
{% assign STATUS_FAILED = 815390004 %}
{% assign STATUS_CANCELLED = 815390005 %}
{% assign STATUS_PENDING_PAYMENT_STR = STATUS_PENDING_PAYMENT | append: '' %}
{% assign STATUS_COMPLETED_STR = STATUS_COMPLETED | append: '' %}
{% assign STATUS_FAILED_STR = STATUS_FAILED | append: '' %}
{% assign STATUS_CANCELLED_STR = STATUS_CANCELLED | append: '' %}

<div class="hit-app-shell">

{% if DEBUG %}
  <div class="hit-debug-panel hit-debug-panel--router-start">
    <div>ROUTER DEBUG START</div>
    <div>acceptanceId={{ acceptanceId }}</div>
  </div>
{% endif %}

{% if acceptanceId == '' %}

  <div class="alert alert-warning">
    Missing acceptance id.
  </div>

{% else %}

  {% if DEBUG %}
    <div class="hit-debug-panel hit-debug-panel--step">
      Step 1: running acceptance fetch
    </div>
  {% endif %}

  {% fetchxml acc %}
  <fetch top="1" mapping="logical">
    <entity name="hit_offeringacceptance">
      <attribute name="hit_offeringacceptanceid" />
      <attribute name="hit_acceptancestatus" />
      <attribute name="hit_paymentrequired" />
      <attribute name="hit_stripeclientsecret" />
      <attribute name="hit_stripepaymentintentid" />

      <link-entity name="hit_offering"
                   from="hit_offeringid"
                   to="hit_offering"
                   alias="off"
                   link-type="outer">
        <attribute name="hit_offeringid" />
        <attribute name="hit_offeringname" />
        <attribute name="hit_offeringtype" />
      </link-entity>

      <filter>
        <condition attribute="hit_offeringacceptanceid"
                   operator="eq"
                   value="{{ acceptanceId }}" />
      </filter>
    </entity>
  </fetch>
  {% endfetchxml %}

  {% assign acceptance = acc.results.entities | first %}

  {% if DEBUG %}
    <div class="hit-debug-panel hit-debug-panel--step">
      <div>Step 2: fetch complete</div>
      <div>acceptance found = {% if acceptance %}true{% else %}false{% endif %}</div>
      <div>result count = {{ acc.results.entities.size }}</div>
    </div>
  {% endif %}

  {% if acceptance %}

    {% if DEBUG %}
      <div class="hit-debug-panel hit-debug-panel--field">
        Step 3: resolving fields
      </div>
    {% endif %}

    {%- comment -%}
    SAFE: acceptance status
    {%- endcomment -%}
    {% assign statusRaw = acceptance.hit_acceptancestatus %}
    {% assign status = '' %}
    {% assign statusLabel = '' %}

    {% if statusRaw %}
      {% assign status = statusRaw.value | default: statusRaw.Value | default: statusRaw.code | default: statusRaw.Code | default: statusRaw %}
      {% assign status = status | append: '' | strip %}

      {% assign statusLabel = statusRaw.label | default: statusRaw.Label | default: '' %}
    {% endif %}

    {% assign routeStatus = status %}
    {% if forceCompletedFromFlow %}
      {% assign routeStatus = STATUS_COMPLETED_STR %}
    {% endif %}

    {%- comment -%}
    SAFE: payment flags
    {%- endcomment -%}
    {% assign requiresPayment = acceptance.hit_paymentrequired | default: false %}
    {% assign isPaymentRequired = false %}
    {% if requiresPayment == true or requiresPayment == 'true' or requiresPayment == 1 or requiresPayment == '1' %}
      {% assign isPaymentRequired = true %}
    {% endif %}
    {% assign clientSecret = acceptance.hit_stripeclientsecret | default: '' | strip %}
    {% assign paymentIntentId = acceptance.hit_stripepaymentintentid | default: '' | strip %}

    {%- comment -%}
    SAFE: linked offering fields
    {%- endcomment -%}
    {% assign offeringType = '' %}
    {% assign offeringName = '' %}
    {% assign offeringTypeExists = false %}
    {% assign offeringNameExists = false %}

    {% if acceptance['off.hit_offeringtype'] %}
      {% assign offeringTypeExists = true %}
      {% assign offTypeRaw = acceptance['off.hit_offeringtype'] %}
      {% if offTypeRaw.value %}
        {% assign offeringType = offTypeRaw.value %}
      {% else %}
        {% assign offeringType = offTypeRaw %}
      {% endif %}
    {% endif %}

    {% if acceptance['off.hit_offeringname'] %}
      {% assign offeringNameExists = true %}
      {% assign offeringName = acceptance['off.hit_offeringname'] %}
    {% endif %}

    {% if DEBUG %}
      <div class="hit-debug-panel hit-debug-panel--resolution">
        <div><strong>Field resolution</strong></div>
        <div>statusRaw exists = {% if statusRaw %}true{% else %}false{% endif %}</div>
        <div>status = {{ status }}</div>
        <div>routeStatus = {{ routeStatus }}</div>
        <div>flowStatusHint = {{ flowStatusHint }}</div>
        <div>statusLabel = {{ statusLabel }}</div>
        <div>requiresPayment = {{ requiresPayment }}</div>
        <div>isPaymentRequired = {{ isPaymentRequired }}</div>
        <div>waitingForStatus = {{ waitingForStatus }}</div>
        <div>clientSecret length = {{ clientSecret | size }}</div>
        <div>paymentIntentId = {{ paymentIntentId }}</div>
        <div>offeringType exists = {{ offeringTypeExists }}</div>
        <div>offeringType = {{ offeringType }}</div>
        <div>offeringName exists = {{ offeringNameExists }}</div>
        <div>offeringName = {{ offeringName }}</div>
      </div>
    {% endif %}

    {% if DEBUG %}
      <div class="hit-debug-panel hit-debug-panel--routing">
        Step 4: entering state routing
      </div>
    {% endif %}

    {% assign isPreparingPayment = false %}
    {% if requiresPayment %}
      {% assign isPreparingPayment = true %}
    {% endif %}

    {% if DEBUG %}
      <div class="hit-debug-panel hit-debug-panel--decision">
        <div>Routing decision</div>
        <div>routeStatus == COMPLETED ? {% if routeStatus == STATUS_COMPLETED_STR %}true{% else %}false{% endif %}</div>
        <div>routeStatus == PENDING_PAYMENT ? {% if routeStatus == STATUS_PENDING_PAYMENT_STR %}true{% else %}false{% endif %}</div>
        <div>routeStatus == FAILED ? {% if routeStatus == STATUS_FAILED_STR %}true{% else %}false{% endif %}</div>
        <div>routeStatus == CANCELLED ? {% if routeStatus == STATUS_CANCELLED_STR %}true{% else %}false{% endif %}</div>
        <div>fallback to acceptance form branch ? 
          {% if routeStatus != STATUS_COMPLETED_STR and routeStatus != STATUS_PENDING_PAYMENT_STR and routeStatus != STATUS_FAILED_STR and routeStatus != STATUS_CANCELLED_STR %}
            true
          {% else %}
            false
          {% endif %}
        </div>
      </div>
    {% endif %}

    {% if routeStatus == STATUS_COMPLETED_STR %}

      {% if isPaymentRequired %}
        {% if DEBUG %}
          <div class="hit-debug-panel hit-debug-panel--include-success">
            Include: sections--confirmation
          </div>
        {% endif %}
        {% include 'sections--confirmation' %}
      {% else %}
        {% if DEBUG %}
          <div class="hit-debug-panel hit-debug-panel--include-success">
            Include: sections--confirmation-nonpayment
          </div>
        {% endif %}
        {% include 'sections--confirmation-nonpayment' %}
      {% endif %}

    {% elsif routeStatus == STATUS_PENDING_PAYMENT_STR %}

      {% if requiresPayment and paymentIntentId == '' %}

        {% if DEBUG %}
          <div class="hit-debug-panel hit-debug-panel--include-payment">
            Include: sections--payment-preparing
          </div>
        {% endif %}
        {% include 'sections--payment-preparing' %}

      {% else %}

        {% if DEBUG %}
          <div class="hit-debug-panel hit-debug-panel--include-payment">
            Include: sections--payment
          </div>
        {% endif %}
        {% include 'sections--payment' %}

      {% endif %}

    {% elsif routeStatus == STATUS_FAILED_STR %}

      <div class="alert alert-danger">
        Payment failed. Please try again.
      </div>

    {% elsif routeStatus == STATUS_CANCELLED_STR %}

      <div class="alert alert-warning">
        This transaction has been cancelled.
      </div>

    {% else %}

      {% if DEBUG %}
        <div class="hit-debug-panel hit-debug-panel--branch">
          Step 5: acceptance form branch
          <div>offeringType for case = {{ offeringType }}</div>
        </div>
      {% endif %}

      {% case offeringType %}
        {% when 815390000 %}
          {% if DEBUG %}
            <div class="hit-debug-panel hit-debug-panel--include-form">
              Include: sections--acceptance-donation
            </div>
          {% endif %}
          {% include 'sections--acceptance-donation' %}

        {% when 815390001 %}
          {% if DEBUG %}
            <div class="hit-debug-panel hit-debug-panel--include-form">
              Include: sections--acceptance-event
            </div>
          {% endif %}
          {% include 'sections--acceptance-event' %}

        {% when 815390002 %}
          {% if DEBUG %}
            <div class="hit-debug-panel hit-debug-panel--include-form">
              Include: sections--acceptance-course
            </div>
          {% endif %}
          {% include 'sections--acceptance-course' acceptanceId: acceptanceId offeringName: offeringName debug: DEBUG %}

        {% when 815390003 %}
          {% if DEBUG %}
            <div class="hit-debug-panel hit-debug-panel--include-form">
              Include: sections--acceptance-membership
            </div>
          {% endif %}
          {% include 'sections--acceptance-membership' %}

        {% when 815390004 %}
          {% if DEBUG %}
            <div class="hit-debug-panel hit-debug-panel--include-form">
              Include: sections--acceptance-volunteer
            </div>
          {% endif %}
          {% include 'sections--acceptance-volunteer' %}

        {% when 815390005 %}
          {% if DEBUG %}
            <div class="hit-debug-panel hit-debug-panel--include-form">
              Include: sections--acceptance-download
            </div>
          {% endif %}
          {% include 'sections--acceptance-download' %}

        {% when 815390006 %}
          {% if DEBUG %}
            <div class="hit-debug-panel hit-debug-panel--include-form">
              Include: sections--acceptance-sponsorship
            </div>
          {% endif %}
          {% include 'sections--acceptance-sponsorship' %}

{% when 815390007 %}
  {% if DEBUG %}
    <div class="hit-debug-panel hit-debug-panel--include-form">
      Include: sections--acceptance-eoi
    </div>
  {% endif %}
  {% include 'sections--acceptance-eoi' acceptanceId: acceptanceId  offeringName: offeringName  debug: DEBUG %}

        {% when 815390008 %}
          {% if DEBUG %}
            <div class="hit-debug-panel hit-debug-panel--include-form">
              Include: sections--acceptance-venue
            </div>
          {% endif %}
          {% include 'sections--acceptance-venue' acceptanceId: acceptanceId debug: DEBUG %}

        {% else %}
          {% if DEBUG %}
            <div class="hit-debug-panel hit-debug-panel--error">
              No acceptance UI configured for offeringType={{ offeringType }}
            </div>
          {% endif %}
          <div class="alert alert-warning">
            No acceptance UI configured for this offering type.
          </div>
      {% endcase %}

    {% endif %}

  {% else %}

    {% if DEBUG %}
      <div class="hit-debug-panel hit-debug-panel--error">
        Acceptance fetch returned no record.
      </div>
    {% endif %}

    <div class="alert alert-warning">
      Acceptance not found.
    </div>

  {% endif %}

{% endif %}

</div>

<script>
(function () {
  var acceptanceId = "{{ acceptanceId | default: '' | escape }}";
  var currentUrl = new URL(window.location.href);
  var flowStatusHint = currentUrl.searchParams.get('flowstatus') || '';
  var waitingForStatus = currentUrl.searchParams.get('waitforpayment') === '1';
  var parsedRouteAttempt = parseInt(currentUrl.searchParams.get('routeattempt') || '0', 10);
  var currentRouteAttempt = Number.isFinite(parsedRouteAttempt) ? parsedRouteAttempt : 0;
  var maximumRouteAttempts = 20;
  var routeRetryDelayMilliseconds = 1250;
  var debugEnabled = "{{ DEBUG | json }}" === "true";
  var pendingPaymentValidationUrl = "{{ settings['Flow/AcceptanceStatusValidation'] | default: '' }}";

  var STATUS_COMPLETED = 815390003;
  var STATUS_PENDING_PAYMENT = 815390001;

  function normaliseStatus(value) {
    if (value === null || value === undefined || value === '') {
      return '';
    }

    if (typeof value === 'object') {
      if (value.value !== undefined && value.value !== null && value.value !== '') {
        return String(value.value);
      }
      if (value.code !== undefined && value.code !== null && value.code !== '') {
        return String(value.code);
      }
      if (value.label !== undefined && value.label !== null && value.label !== '') {
        return String(value.label);
      }
      return '';
    }

    return String(value);
  }

  function buildRouterUrl(attempt) {
    var targetUrl = new URL(window.location.pathname, window.location.origin);
    targetUrl.searchParams.set('page', 'offering-acceptance');
    targetUrl.searchParams.set('acceptanceid', acceptanceId);
    targetUrl.searchParams.set('waitforpayment', '1');
    targetUrl.searchParams.set('routeattempt', String(attempt));
    targetUrl.searchParams.set('_ts', String(Date.now()));
    return targetUrl.toString();
  }

  function refreshRouterWithoutWait(flowStatus) {
    var targetUrl = new URL(window.location.pathname, window.location.origin);
    targetUrl.searchParams.set('page', 'offering-acceptance');
    targetUrl.searchParams.set('acceptanceid', acceptanceId);
    if (flowStatus) {
      targetUrl.searchParams.set('flowstatus', flowStatus);
    }
    targetUrl.searchParams.set('_ts', String(Date.now()));
    window.location.replace(targetUrl.toString());
  }

  function stopRouterRetry() {
    var cleanUrl = new URL(window.location.href);
    cleanUrl.searchParams.delete('waitforpayment');
    cleanUrl.searchParams.delete('routeattempt');
    cleanUrl.searchParams.delete('flowstatus');
    cleanUrl.searchParams.delete('_ts');
    window.history.replaceState({}, document.title, cleanUrl.toString());
  }

  function clearFlowStatusHintFromUrl() {
    if (!flowStatusHint) {
      return;
    }

    var cleanUrl = new URL(window.location.href);
    cleanUrl.searchParams.delete('flowstatus');
    window.history.replaceState({}, document.title, cleanUrl.toString());
  }

  function pollForCompletion() {
    if (!acceptanceId) {
      return;
    }

    if (currentRouteAttempt >= maximumRouteAttempts) {
      stopRouterRetry();
      return;
    }

    if (!pendingPaymentValidationUrl) {
      if (debugEnabled) {
        console.log('[acceptance-router] no validation URL configured; stopping retry', {
          acceptanceId: acceptanceId,
          routeAttempt: currentRouteAttempt
        });
      }

      stopRouterRetry();
      return;
    }

    fetch(pendingPaymentValidationUrl, {
      method: 'POST',
      credentials: 'same-origin',
      cache: 'no-store',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'Cache-Control': 'no-store, no-cache, must-revalidate, max-age=0',
        'Pragma': 'no-cache',
        'Expires': '0'
      },
      body: JSON.stringify({
        acceptanceId: acceptanceId
      })
    })
      .then(function (res) {
        if (!res.ok) throw new Error('pending payment validation failed: ' + res.status);
        return res.json();
      })
      .then(function (data) {
        var statusValue = normaliseStatus(data && data.hit_acceptancestatus);

        if (debugEnabled) {
          console.log('[acceptance-router] validation result', {
            acceptanceId: acceptanceId,
            statusValue: statusValue,
            routeAttempt: currentRouteAttempt
          });
        }

        if (String(statusValue) === String(STATUS_COMPLETED)) {
          refreshRouterWithoutWait('completed');
          return;
        }

        if (String(statusValue) === String(STATUS_PENDING_PAYMENT)) {
          if (debugEnabled) {
            console.log('[acceptance-router] pending payment confirmed; stopping retries', {
              acceptanceId: acceptanceId,
              routeAttempt: currentRouteAttempt,
              statusValue: statusValue
            });
          }

          stopRouterRetry();
          return;
        }

        setTimeout(function () {
          window.location.replace(buildRouterUrl(currentRouteAttempt + 1));
        }, routeRetryDelayMilliseconds);
      })
      .catch(function () {
        if (debugEnabled) {
          console.log('[acceptance-router] validation failed; retrying', { acceptanceId: acceptanceId, routeAttempt: currentRouteAttempt });
        }

        setTimeout(function () {
          window.location.replace(buildRouterUrl(currentRouteAttempt + 1));
        }, routeRetryDelayMilliseconds);
      });
  }

  if (waitingForStatus) {
    pollForCompletion();
    return;
  }

  clearFlowStatusHintFromUrl();
})();
</script>


"
}
